// Decorative corner HUD markers
const Corner: React.FC<{
  position: "top-left" | "top-right" | "bottom-left" | "bottom-right";
  color: string;
  size: number;
}> = ({ position, color, size }) => {
  const style: React.CSSProperties = {
    position: "absolute",
    width: size,
    height: size,
    borderColor: color,
    borderStyle: "solid",
    borderWidth: 0,
    transition: "none",
  };

  if (position === "top-left") {
    style.top = 0;
    style.left = 0;
    style.borderTopWidth = 2;
    style.borderLeftWidth = 2;
  } else if (position === "top-right") {
    style.top = 0;
    style.right = 0;
    style.borderTopWidth = 2;
    style.borderRightWidth = 2;
  } else if (position === "bottom-left") {
    style.bottom = 0;
    style.left = 0;
    style.borderBottomWidth = 2;
    style.borderLeftWidth = 2;
  } else if (position === "bottom-right") {
    style.bottom = 0;
    style.right = 0;
    style.borderBottomWidth = 2;
    style.borderRightWidth = 2;
  }

  return <div style={style} />;
};

// Binary fluctuation grid
const BinaryGrid: React.FC<{
  columns: number;
  rows: number;
  color: string;
  seed: string;
}> = ({ columns, rows, color, seed }) => {
  const frame = useCurrentFrame();

  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: `repeat(${columns}, 1fr)`,
        gap: "4px",
        fontFamily: robotoMonoFamily,
        fontSize: "11px",
        color,
        opacity: 0.2,
        transition: "none",
      }}
    >
      {Array.from({ length: rows }).map((_, r) =>
        Array.from({ length: columns }).map((__, c) => {
          const randVal = Math.floor(
            random(`${seed}-${r}-${c}-${Math.floor(frame / 8)}`) * 2
          );
          return (
            <div key={`${r}-${c}`} style={{ transition: "none" }}>
              {randVal}
            </div>
          );
        })
      )}
    </div>
  );
};

// Single matrix falling binary stream
const MatrixStream: React.FC<{
  x: number;
  speed: number;
  delay: number;
  color: string;
  height: number;
}> = ({ x, speed, delay, color, height }) => {
  const frame = useCurrentFrame();
  const y = ((frame - delay) * speed) % (height + 200) - 100;

  if (frame < delay) return null;

  return (
    <div
      style={{
        position: "absolute",
        left: `${x}%`,
        top: y,
        color,
        fontSize: 14,
        lineHeight: "16px",
        opacity: 0.12,
        fontFamily: robotoMonoFamily,
        whiteSpace: "pre-wrap",
        display: "flex",
        flexDirection: "column",
        transition: "none",
      }}
    >
      {Array.from({ length: 10 }).map((_, i) => {
        const char = (Math.floor(frame / (4 + (i % 3))) + i) % 2;
        return <div key={i}>{char}</div>;
      })}
    </div>
  );
};

// Cyber loading indicator bar
const CyberLoadingBar: React.FC<{
  progress: number;
  color: string;
}> = ({ progress, color }) => {
  const totalBlocks = 12;
  const filledBlocks = Math.floor(progress * totalBlocks);

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        gap: "3px",
        fontFamily: robotoMonoFamily,
        color,
        fontSize: "13px",
        marginTop: "10px",
        transition: "none",
      }}
    >
      <span style={{ marginRight: "6px", fontWeight: "bold", opacity: 0.8 }}>SYSTEM_BOOT:</span>
      {Array.from({ length: totalBlocks }).map((_, i) => {
        const isFilled = i < filledBlocks;
        return (
          <div
            key={i}
            style={{
              width: "10px",
              height: "10px",
              backgroundColor: isFilled ? color : "transparent",
              border: `1px solid ${color}`,
              boxShadow: isFilled ? `0 0 6px ${color}` : "none",
              opacity: isFilled ? 1 : 0.2,
              transition: "none",
            }}
          />
        );
      })}
      <span style={{ marginLeft: "6px", fontWeight: "bold" }}>
        {Math.floor(progress * 100)}%
      </span>
    </div>
  );
};

