// Helper functions for character-level typewriter progression
const getLinesProgress = (lines: string[], progress: number) => {
  const totalChars = lines.reduce((acc, line) => acc + line.length, 0);
  const targetCharCount = Math.floor(progress * totalChars);

  let charsRemaining = targetCharCount;
  const result: string[] = [];

  for (const line of lines) {
    if (charsRemaining <= 0) {
      break;
    }
    if (charsRemaining >= line.length) {
      result.push(line);
      charsRemaining -= line.length;
    } else {
      result.push(line.slice(0, charsRemaining));
      charsRemaining = 0;
    }
  }
  return result;
};

// Syntactic highlighter for Py terminal look
const highlightPythonLine = (
  line: string,
  primaryColor: string,
  textColor: string
) => {
  const keywords = [
    "import",
    "class",
    "def",
    "return",
    "if",
    "else",
    "from",
    "for",
    "in",
  ];
  const builtins = ["print", "len", "sys", "os", "json", "hashlib", "datetime"];
  const selfWord = ["self"];

  const parts = line.split(/(\s+|=|\(|\)|\[|\]|:|\.|"|')/);

  return (
    <>
      {parts.map((part, index) => {
        let color = textColor;
        let fontWeight = "normal";

        if (keywords.includes(part.trim())) {
          color = primaryColor;
          fontWeight = "bold";
        } else if (builtins.includes(part.trim())) {
          color = "#00FFC2";
        } else if (selfWord.includes(part.trim())) {
          color = "#FFD700";
        } else if (
          part.startsWith('"') ||
          part.endsWith('"') ||
          part.startsWith("'") ||
          part.endsWith("'")
        ) {
          color = "#A8FF58";
        } else if (part === "=" || part === ":" || part === ".") {
          color = primaryColor;
        }

        return (
          <span key={index} style={{ color, fontWeight, transition: "none" }}>
            {part}
          </span>
        );
      })}
    </>
  );
};

// Terminal Output highlighting
const highlightConsoleLine = (
  line: string,
  primaryColor: string,
  textColor: string
) => {
  if (line.startsWith("$")) {
    return (
      <span style={{ color: "#ffffff", fontWeight: "bold" }}>
        <span style={{ color: primaryColor }}>$</span> {line.slice(1)}
      </span>
    );
  }
  if (line.startsWith("[+]")) {
    return (
      <span>
        <span style={{ color: primaryColor, fontWeight: "bold" }}>[+]</span>{" "}
        <span style={{ color: textColor }}>{line.slice(3)}</span>
      </span>
    );
  }
  if (line.startsWith("[!]")) {
    return (
      <span>
        <span style={{ color: "#FF3333", fontWeight: "bold" }}>[!]</span>{" "}
        <span style={{ color: textColor }}>{line.slice(3)}</span>
      </span>
    );
  }
  return <span style={{ color: textColor }}>{line}</span>;
};

